"use client";
/**
 * StarSlider — a 1–5 star rating bar that fills in shades of blue (React 18/19, no deps).
 *  Tap a star or drag along the bar: the fill follows the pointer smoothly and settles on the nearest star when you let
 *  go. One star is a pale sky blue; toward five the fill deepens to royal blue, a gradient that runs from a lighter blue
 *  at its left to the current shade at its tip. Lit stars turn white and pop (×1.15). ← → keys change it by one.
 *  "Not for me" and "Love it" under the bar (labels="" hides them).
 * Autoplay: the fill sweeps up to five stars and back on a loop; any touch or key stops it. Reduced motion: no sweep.
 * What you get: the bar (400px wide by default). The white page around it is only the demo backdrop; backdrop={false} =
 *  just the bar on a transparent box.
 * Kit-ready: "use client", SSR-safe, no viewport units, CSS in this file (scoped under .ssl) with a small kit-shield block.
 */
import { useEffect, useRef, useState, type CSSProperties } from "react";

export type StarSliderProps = {
  value?: number;                                  // controlled rating 0–5
  defaultValue?: number;                           // (0)
  onChange?: (rating: number) => void;             // 1–5, when someone picks
  shades?: [number, number, number][];             // five RGB stops, pale → deep (sky → royal blue)
  track?: string;                                  // the empty bar ("#f2f2f0")
  starOff?: string;                                // unlit stars ("#c9c9c6")
  starOn?: string;                                 // lit stars ("#ffffff")
  height?: number;                                 // px (52)
  radius?: number;                                 // px (16)
  width?: number;                                  // px (400)
  lowLabel?: string;                               // ("Not for me"); "" hides both labels
  highLabel?: string;                              // ("Love it")
  ariaLabel?: string;                              // ("Rating")
  fontFamily?: string;
  loadFont?: boolean;                              // load Inter (true)
  backdrop?: boolean;                              // the white demo page (true)
  autoplay?: boolean;                              // (false)
  simulate?: boolean;                              // same as autoplay
  className?: string;
  style?: CSSProperties;
};

const STAR = "m12 3.5 2.6 5.3 5.9.9-4.3 4.1 1 5.8L12 16.9l-5.2 2.7 1-5.8-4.3-4.1 5.9-.9z";
const SHADES: [number, number, number][] = [[176, 218, 255], [118, 184, 255], [64, 140, 255], [47, 107, 255], [38, 72, 232]];

export default function StarSlider({
  value, defaultValue = 0, onChange, shades = SHADES, track = "#f2f2f0", starOff = "#c9c9c6", starOn = "#ffffff",
  height = 52, radius = 16, width = 400, lowLabel = "Not for me", highLabel = "Love it", ariaLabel = "Rating",
  fontFamily = "Inter, ui-sans-serif, system-ui, sans-serif", loadFont = true, backdrop = true, autoplay = false, simulate = false,
  className, style,
}: StarSliderProps) {
  const [inner, setInner] = useState(defaultValue);
  const rating = value ?? inner;
  const bar = useRef<HTMLDivElement>(null), fill = useRef<HTMLElement>(null), stars = useRef<(HTMLSpanElement | null)[]>([]);
  const st = useRef({ v: rating, target: rating, drag: false, raf: 0, auto: false });
  const sh = useRef(shades); sh.current = shades;

  // the fill's colour: a shade between the five stops for a value 1–5
  const mix = (v: number) => {
    const S = sh.current, t = Math.max(0, Math.min(4, v - 1)), i = Math.min(3, Math.floor(t)), k = t - i, a = S[i], b = S[i + 1];
    return a.map((x, j) => Math.round(x + (b[j] - x) * k)).join(",");
  };
  const paint = () => {
    const s = st.current, f = fill.current; if (!f) return;
    f.style.width = (s.v / 5) * 100 + "%";
    f.style.background = `linear-gradient(90deg, rgb(${mix(Math.max(1, s.v - 1.6))}) 0%, rgb(${mix(Math.max(1, s.v))}) 100%)`;
    const lit = s.drag ? Math.ceil(s.v - 0.15) : Math.round(s.v);
    stars.current.forEach((el, i) => el && el.classList.toggle("on", i < lit));
  };
  // the fill eases toward its target at 0.22 a frame
  const tick = () => { const s = st.current; s.v += (s.target - s.v) * 0.22; if (Math.abs(s.target - s.v) < 0.002) s.v = s.target; paint(); s.raf = s.v !== s.target ? requestAnimationFrame(tick) : 0; };
  const go = (t: number) => { st.current.target = t; if (!st.current.raf) st.current.raf = requestAnimationFrame(tick); };
  const pick = (r: number) => { go(r); if (value === undefined) setInner(r); onChange?.(r); };
  const x2v = (x: number) => { const r = bar.current!.getBoundingClientRect(); return Math.max(0.35, Math.min(5, ((x - r.left) / r.width) * 5)); };
  const up = () => { const s = st.current; if (!s.drag) return; s.drag = false; pick(Math.max(1, Math.min(5, Math.ceil(s.target - 0.15)))); };

  useEffect(() => { paint(); return () => cancelAnimationFrame(st.current.raf); }, []); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (value !== undefined && !st.current.drag) go(value); }, [value]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (!loadFont || document.querySelector("link[data-ssl-font]")) return;
    const l = document.createElement("link"); l.rel = "stylesheet"; l.href = "https://fonts.googleapis.com/css2?family=Inter:wght@400;500&display=swap"; l.setAttribute("data-ssl-font", ""); document.head.appendChild(l);
  }, [loadFont]);

  // autoplay: sweep 1 → 5, hold, back to none; any touch or key stops it
  useEffect(() => {
    if (!(autoplay || simulate) || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const s = st.current; s.auto = true;
    const seq = [1, 2, 3, 4, 5, 5, 5, 4, 3, 0, 0];
    let i = 0;
    const id = setInterval(() => { if (!s.auto || s.drag) return; go(seq[i++ % seq.length]); }, 520);
    const stop = (e: Event) => { if (e.isTrusted) { s.auto = false; clearInterval(id); } };
    window.addEventListener("pointerdown", stop, true); window.addEventListener("keydown", stop, true);
    return () => { s.auto = false; clearInterval(id); window.removeEventListener("pointerdown", stop, true); window.removeEventListener("keydown", stop, true); };
  }, [autoplay, simulate]); // eslint-disable-line react-hooks/exhaustive-deps

  const vars = { "--ssl-w": `${width}px`, "--ssl-h": `${height}px`, "--ssl-r": `${radius}px`, "--ssl-track": track, "--ssl-off": starOff, "--ssl-on": starOn,
    "--ssl-page": backdrop ? "#ffffff" : "transparent", fontFamily } as CSSProperties;

  return (
    <div className={`ssl${backdrop ? " ssl-bd" : ""}${className ? " " + className : ""}`} style={{ ...vars, ...style }}>
      <style>{CSS}</style>
      <div className="ssl-in">
        <div ref={bar} className="ssl-bar" role="slider" aria-label={ariaLabel} aria-valuemin={1} aria-valuemax={5} aria-valuenow={rating || 0} tabIndex={0}
          onKeyDown={(e) => { if (e.key === "ArrowRight" || e.key === "ArrowLeft") { e.preventDefault(); pick(Math.max(1, Math.min(5, (rating || 0) + (e.key === "ArrowRight" ? 1 : -1)))); } }}
          onPointerDown={(e) => { st.current.drag = true; bar.current!.setPointerCapture(e.pointerId); go(x2v(e.clientX)); }}
          onPointerMove={(e) => { if (st.current.drag) go(x2v(e.clientX)); }}
          onPointerUp={up} onPointerCancel={up}>
          <i ref={fill} className="ssl-fill" />
          <div className="ssl-stars">
            {[0, 1, 2, 3, 4].map((i) => <span key={i} ref={(el) => { stars.current[i] = el; }}><svg viewBox="0 0 24 24" aria-hidden="true"><path d={STAR} /></svg></span>)}
          </div>
        </div>
        {lowLabel !== "" && <div className="ssl-lab"><span>{lowLabel}</span><span>{highLabel}</span></div>}
      </div>
    </div>
  );
}

const CSS = `/* kit-shield: undo Tailwind preflight inside the component (Kit) */
:where(.ssl) { line-height: normal; color: CanvasText; tab-size: 8; font-feature-settings: normal; font-variation-settings: normal; -webkit-text-size-adjust: auto; -webkit-tap-highlight-color: initial; }
:where(.ssl) :where(*), :where(.ssl) :where(*)::before, :where(.ssl) :where(*)::after { box-sizing: border-box; margin: revert; padding: revert; border-width: revert; border-style: revert; border-color: revert; outline-color: revert; }
:where(.ssl) :where(svg) { display: revert; vertical-align: revert; max-width: revert; height: revert; }

.ssl { box-sizing: border-box; position: relative; width: 100%; display: flex; justify-content: center; background: var(--ssl-page); color: #0b0b0b; -webkit-font-smoothing: antialiased; }
.ssl.ssl-bd { padding: 56px 16px; min-height: 100vh; align-items: center; }   /* the white page fills the whole preview */
.ssl .ssl-in { width: min(var(--ssl-w), 100%); }
.ssl .ssl-bar { position: relative; height: var(--ssl-h); border-radius: var(--ssl-r); background: var(--ssl-track); overflow: hidden; cursor: pointer; touch-action: none; user-select: none; outline: none; }
.ssl .ssl-bar:focus-visible { box-shadow: 0 0 0 2px #2f6bff; }
.ssl .ssl-fill { position: absolute; left: 0; top: 0; bottom: 0; width: 0; border-radius: var(--ssl-r); }
.ssl .ssl-stars { position: absolute; inset: 0; display: flex; justify-content: space-around; align-items: center; pointer-events: none; }
.ssl .ssl-stars span { display: grid; transition: transform .35s cubic-bezier(.3,1.8,.5,1); }
.ssl .ssl-stars svg { display: block; width: 22px; height: 22px; fill: var(--ssl-off); transition: fill .2s; }
.ssl .ssl-stars span.on { transform: scale(1.15); }
.ssl .ssl-stars span.on svg { fill: var(--ssl-on); }
.ssl .ssl-lab { display: flex; justify-content: space-between; margin: 8px 2px 0; font-size: 12px; color: #9a9a9a; }
@media (prefers-reduced-motion: reduce) { .ssl .ssl-stars span, .ssl .ssl-stars svg { transition: none; } }
`;

